import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from './common';
import './CustomersPage.css';

export default function CustomersPage({leads}) { const customers=leads.filter(l=>['Won','Negotiation','Site Visit'].includes(l.status)); return <div className="module-page module-page--customers"><PageTitle eyebrow="RELATIONSHIP HUB" title="Customers" subtitle="Customers and qualified opportunities in one place."/><div className="panel"><div className="panel-head"><div><h3>Customer directory</h3><p>Derived from active and converted leads in this demo.</p></div><span className="table-count">{customers.length} contacts</span></div><div className="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>CONTACT</th><th>PROPERTY INTEREST</th><th>OWNER</th><th>STAGE</th></tr></thead><tbody>{customers.map((l,i)=><tr key={l.id}><td><div className="contact-cell"><div className={`tiny-avatar av-${i%4}`}>{l.name[0]}</div><b>{l.name}</b></div></td><td>{l.phone}<small className="cell-sub">{l.email}</small></td><td>{l.type}<small className="cell-sub">{l.location}</small></td><td>{l.assigned}</td><td><Status value={l.status}/></td></tr>)}</tbody></table></div></div></div>; }
